-- Missions: an account's own goals, the tasks under them and the time
-- tracked on those tasks, synced between the account's devices.
--
-- Same conventions as every table before these: STRICT, and every
-- timestamp is an INTEGER Unix second. Calendar days (`starts_on`,
-- `ends_on`, `day`) are TEXT 'YYYY-MM-DD' in the account's time zone,
-- because a day is not an instant.
--
-- # Keys
--
-- Every record's id is generated by the client (32 lowercase hex
-- characters, same form as `events.event_id`), so a device can create
-- records offline. The primary key is `(user_id, id)`: an id is only
-- unique within one account, and the composite foreign keys below make
-- it impossible for one account's task to point at another account's
-- mission. They are DEFERRABLE INITIALLY DEFERRED so a cascade from
-- `users` may delete parents before children within one statement; the
-- application checks references itself before writing (see
-- `crate::missions::store`), so these are the second line.
--
-- # Sync
--
-- `updated_at` is the client's clock at the last edit; last write wins
-- on it, per record. `rev` is the server's ordering: every write takes
-- the next value of `users.missions_rev`, one counter shared by all
-- three tables, so "everything after cursor N" is one comparison.
--
-- A delete is a tombstone (`deleted = 1`) rather than a removed row, so
-- other devices learn about it. A tombstone keeps no text: the CHECKs
-- below refuse a deleted row with a title, description, why or notes.

ALTER TABLE users ADD COLUMN missions_rev INTEGER NOT NULL DEFAULT 0;

CREATE TABLE missions (
    user_id          TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    id               TEXT    NOT NULL,
    title            TEXT    NOT NULL,
    -- One of the dashboard's palette slots, `--cat-0` to `--cat-7`.
    colour           INTEGER NOT NULL,
    -- 0 means no goal.
    weekly_goal_secs INTEGER NOT NULL,
    description      TEXT,
    why              TEXT,
    starts_on        TEXT,
    ends_on          TEXT,
    archived         INTEGER NOT NULL,
    deleted          INTEGER NOT NULL,
    updated_at       INTEGER NOT NULL,
    rev              INTEGER NOT NULL,

    PRIMARY KEY (user_id, id),
    CHECK (colour BETWEEN 0 AND 7),
    CHECK (weekly_goal_secs BETWEEN 0 AND 604800),
    CHECK (archived IN (0, 1)),
    CHECK (deleted IN (0, 1)),
    CHECK (length(title) <= 100),
    CHECK (description IS NULL OR length(description) <= 2000),
    CHECK (why IS NULL OR length(why) <= 2000),
    CHECK (CASE deleted
               WHEN 1 THEN title = '' AND description IS NULL AND why IS NULL
               ELSE length(title) >= 1
           END)
) STRICT;

CREATE UNIQUE INDEX missions_user_id_rev_idx ON missions (user_id, rev);

CREATE TABLE tasks (
    user_id    TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    id         TEXT    NOT NULL,
    -- NULL: the task belongs to no mission ("Other").
    mission_id TEXT,
    title      TEXT    NOT NULL,
    notes      TEXT,
    -- NULL: the backlog, planned for no day.
    day        TEXT,
    -- A fractional index key; tasks of one day sort by it, bytewise.
    position   TEXT    NOT NULL,
    -- NULL while open.
    done_at    INTEGER,
    deleted    INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    rev        INTEGER NOT NULL,

    PRIMARY KEY (user_id, id),
    FOREIGN KEY (user_id, mission_id) REFERENCES missions (user_id, id)
        DEFERRABLE INITIALLY DEFERRED,
    CHECK (deleted IN (0, 1)),
    CHECK (length(title) <= 200),
    CHECK (notes IS NULL OR length(notes) <= 4000),
    CHECK (length(position) BETWEEN 1 AND 64),
    CHECK (CASE deleted
               WHEN 1 THEN title = '' AND notes IS NULL
               ELSE length(title) >= 1
           END)
) STRICT;

CREATE UNIQUE INDEX tasks_user_id_rev_idx ON tasks (user_id, rev);
-- The foreign key's child side, so checking it is not a table scan.
CREATE INDEX tasks_user_id_mission_id_idx ON tasks (user_id, mission_id);

CREATE TABLE time_entries (
    user_id    TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    id         TEXT    NOT NULL,
    task_id    TEXT    NOT NULL,
    start_ts   INTEGER NOT NULL,
    -- NULL while the timer runs.
    end_ts     INTEGER,
    deleted    INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    rev        INTEGER NOT NULL,

    PRIMARY KEY (user_id, id),
    FOREIGN KEY (user_id, task_id) REFERENCES tasks (user_id, id)
        DEFERRABLE INITIALLY DEFERRED,
    CHECK (deleted IN (0, 1)),
    -- `>=`, not `>`: two timers started in the same second end the
    -- older one at its own start.
    CHECK (end_ts IS NULL OR end_ts >= start_ts)
) STRICT;

CREATE UNIQUE INDEX time_entries_user_id_rev_idx ON time_entries (user_id, rev);
CREATE INDEX time_entries_user_id_task_id_idx ON time_entries (user_id, task_id);

-- One running timer per account. The application ends the older entry
-- before writing a newer one; this index is what makes a second running
-- entry impossible rather than merely unlikely.
CREATE UNIQUE INDEX time_entries_one_running_idx
    ON time_entries (user_id) WHERE end_ts IS NULL AND deleted = 0;

UPDATE schema_info SET schema_version = 8 WHERE id = 1;
